    "s27_p4_bullet_1": "<strong>Homogener Filzstreifen:</strong> Aus einem Stück 3D-gepresst – garantiert bruchlose Übergänge über alle 88 Tasten.",
    "s27_p4_bullet_2": "<strong>Differenzierter Bass:</strong> Austarierte Masse und elastischer Filz für tiefe Grundtönigkeit und saubere Tontrennung.",
