    "s28_bullet_2": "<strong>Plug &amp; Play Montage:</strong> Direktes Einschrauben der kalibrierten Kapseln ins originale Alu-Profil.",
    "s28_bullet_3": "<strong>Feinregulation vor Ort:</strong> Exaktes Einstellen von Steighöhe, Auslösung und Fang direkt am Flügel.",
    "s28_bullet_4": "<strong>Null Transportrisiko:</strong> Der Flügel bleibt im Raum und wird unmittelbar auf die Akustik abgestimmt.",
