    "s28_c1_desc": "Zeitraffer aus Indien: Taggleicher Einbau des Renner Yamaha Kits samt Feinregulation von 10 bis 18 Uhr.",
    "s28_fact": "⏱ 10:00–18:00 Uhr: Vom Ausbau bis zum konzertfertigen Flügel vor Ort",
    "s28_notes": "Folie 28: Zeigen Sie das Zeitraffer-Video des kompletten Einbaus in Indien (10:00 bis 18:00 Uhr). Innerhalb eines einzigen Arbeitstages vor Ort wurde der Yamaha-Flügel vollständig auf das vorkonfektionierte Louis Renner Yamaha Kit umgerüstet und feinreguliert.",
