    "s29_notes": "Folie 29: Spielen Sie das Feedback-Video der Pianistin Raaga ab. Sie beschreibt unmittelbar nach dem Einbau des Louis Renner Yamaha Kits den deutlich wärmeren, singenden Konzertton sowie die feinfühlige Kontrolle vom Pianissimo bis zum Fortissimo.",
