    "s33_exp_badge": "✦ AKUSTISCHE WIRKUNG IM KLAVIERTON",
    "s33_notes": "Folie 33 (Auftakt Kapitel 5: Intonation): Zeigen Sie interaktiv am tiefen A₁ (55 Hz, klingende Länge L = 1.560 mm), wie sich ein Klavierton aus seinen harmonischen Teiltönen H₁–H₁₂ zusammensetzt. Demonstrieren Sie zuerst die Tonhärte: Ein weicherer, genadelter Hammerkopf verlängert die Kontaktzeit τc (~3,8 ms) und senkt hohe Obertöne in dB ab, während ein härterer Scheitel (τc ~1,3 ms) hohe Teiltöne stark anhebt. Zeigen Sie danach am Saitenmodell das Young-Helmholtz-Gesetz: Bei 1/8 L bzw. 1/7 L dämpft der Hammer gezielt scharfe Reibungstöne (H₇ Naturseptime, H₉ Sekunde) im Schwingungsknoten ab, ohne die singende Dur-Terz H₅ (1/5 L) zu verlieren.",
    "s34_category": "Teil 5: Intonation • Vorintonation",
    "s34_title": "Vorintonation (Pre-Needling): Tiefe Stiche im ff-Keil",
    "s34_subtitle": "Abbau werkseitiger Vorspannung und Energieübertragung in den Forte-Keil",
    "s34_bullet_1": "<strong>Arbeitszone:</strong> Ausschließlich im blauen Fortissimo-Keil (9:00–10:00 Uhr bzw. 2:00–3:00 Uhr) arbeiten.",
    "s34_bullet_2": "<strong>Tiefe Einstiche:</strong> Ruhig bis kurz vor den Unterfilz führen – niemals in Unterfilz oder Holzkern stechen!",
    "s34_bullet_3": "<strong>Spannungstransfer:</strong> Die starre Werkshärte weicht; elastische Energie fließt in den grünen Forte-Keil.",
    "s34_bullet_4": "<strong>Praxis-Empfehlung:</strong> Vor dem ersten Anspielen im Flügel fast ausnahmslos als Fundament anzuraten.",
    "s34_caption_1": "Pre-Needling: Tiefe Stiche im Fortissimo-Keil (9:00 bis 10:00 Uhr)",
    "s34_b1_badge": "PRE-NEEDLING",
    "s34_b2_badge": "GRUNDELASTIZITÄT",
    "s34_c1_desc": "Die Vorintonation ist der entscheidende Basisschritt bei fabrikneuen oder neu befilzten Hammerköpfen.",
    "s34_kpi": "pp – ff",
    "s34_c1_title": "Gezielter Spannungsabbau im blauen Fortissimo-Keil",
    "s34_fact": "🎯 Öffnet das elastische Klangvolumen, ohne die Scheitelkrone zu schwächen",
    "s34_notes": "Folie 39: Erläutern Sie die wesentlichen technischen Parameter und Qualitätskriterien aus den Renner Academy Unterlagen.",
    "s35_category": "Teil 5: Intonation • Werkzeug & Technik",
    "s35_title": "Nadelstich-Vorgaben & Intonierwerkzeuge",
    "s35_subtitle": "Drücken statt Hacken – Exakte Stichanzahlen für Bass, Mittellage und Diskant",
    "s35_bullet_1": "<strong>Bass &amp; Mittellage:</strong> Horizontaler Einstich im ff-Keil mit 7–10 Stichen im Bass und 5–10 Stichen in der Mitte.",
    "s35_bullet_2": "<strong>Diskant-Dosierung:</strong> Vertikal geführte Einstiche mit 0–7 Stichen je nach gewünschter Brillanz und Tragkraft.",
    "s35_bullet_3": "<strong>Drücken, niemals hacken:</strong> Nadeln ruhig mit Körpergewicht führen – Hacken zerreißt das Fasergefüge irreversibel!",
    "s35_caption_1": "Renner Intonierwerkzeuge, Nadelhalter und Intonierapparat",
    "s35_b1_badge": "WERKZEUGKUNDE",
    "s35_b2_badge": "PRÄZISIONSNADELN",
    "s35_kpi": "Nr. 7 · ø 0,60 mm",
    "s35_c1_title": "Richtwerte pro Register & schonende Nadelführung",
    "s35_c1_desc": "Ruhiges Eindrücken mit Original-Werkzeugen verdrängt die Wollfasern kontrolliert, statt sie zu zerreißen.",
    "s35_bullet_4": "<strong>Original Renner Werkzeuge:</strong> Intonierapparat (43-0005642), 3er-Profi-Halter (43-0003270) und Nadeln Nr. 7 (43-0003426).",
    "s35_fact": "🛠 Glatte vernickelte Nadeln (ø 0,60 mm, 9 mm) gleiten faserschonend ins Vlies",
    "s35_notes": "Folie 40: Erläutern Sie die wesentlichen technischen Parameter und Qualitätskriterien aus den Renner Academy Unterlagen.",
    "s36_category": "Teil 5: Intonation • Saitenlagerung",
    "s36_title": "Saitenvorbereitung: Anhangstifte, Stegstifte & Agraffen",
    "s36_subtitle": "„Der beste Hammerkopf kann nur das hervorbringen, was im Instrument programmiert ist!“",
    "s36_caption_1": "Saiten niederschlagen am Anhangstift mit Messingdurchschlag",
    "s36_b1_badge": "SAITEN-BETTUNG",
    "s36_b2_badge": "CHORREINHEIT",
    "s36_bullet_1": "<strong>Anhangstifte setzen:</strong> Saiten von hinten nach vorn mit Messingdurchschlag und leichtem Hammer sanft anlegen.",
    "s36_bullet_2": "<strong>Stegstifte anpassen:</strong> Mit dem Renner-Setzer die Saiten sauber auf den Steg drücken, um Nebentöne zu eliminieren.",
    "s36_bullet_3": "<strong>Reine Chorstimmung:</strong> Vor jeder Nadelarbeit muss jeder 3er-Chor absolut schwebungs- und nebengeräuschfrei stehen.",
    "s36_kpi": "100 % Chorrein",
    "s36_c1_title": "Exakte Saitenauflage vor dem ersten Nadelstich",
    "s36_c1_desc": "Nur sauber aufliegende und rein gestimmte Saitenchöre erlauben eine ehrliche klangliche Diagnose am Hammerkopf.",
    "s36_fact": "🎵 Goldene Regel: Keine Nadel korrigiert einen unsauber gelagerten Saitenchor!",
    "s36_notes": "Folie 41: Erläutern Sie die wesentlichen technischen Parameter und Qualitätskriterien aus den Renner Academy Unterlagen.",
    "s37_category": "Teil 5: Intonation • Ausrichtung",
    "s37_title": "Anschlagspunkt im Diskant & Geradheitsprüfung",
    "s37_subtitle": "Optimierung der Noten 69–88 durch Verschieben des Klaviaturrahmens",
    "s37_bullet_1": "<strong>Referenzton Note 88:</strong> Klaviaturrahmen minimal vor- und zurückschieben, bis der hellste, vollste Ton einrastet.",
    "s37_bullet_2": "<strong>Diskantfenster 69–88:</strong> Eine exakte Justierung des Anschlagspunkts hebt das Klangvolumen vieler Flügel dramatisch.",
    "s37_bullet_3": "<strong>Geradheit &amp; Flucht:</strong> Kontrolle durch sanftes Anheben an der Klinke oder Zupfhaken; Korrekturbedarf auf der Taste markieren.",
    "s37_caption_1": "Prüfung des Diskant-Anschlagspunkts und Ausrichtung der Hämmer",
    "s37_b1_badge": "STRIKE POINT",
    "s37_b2_badge": "DISKANTGLANZ",
    "s37_kpi": "Note 69–88",
    "s37_c1_title": "Optimaler Anschlagspunkt & präzise Hammerflucht",
    "s37_c1_desc": "Bereits Millimeterbruchteile der Klaviaturposition entscheiden im hohen Diskant über Tragkraft und Obertonglanz.",
    "s37_fact": "✨ Perfekte Mechanikgeometrie vor der Feinintonation spart unnötige Nadelarbeit",
    "s37_notes": "Folie 42: Erläutern Sie die wesentlichen technischen Parameter und Qualitätskriterien aus den Renner Academy Unterlagen.",
