    "s39_category": "Teil 5: Intonation • Feinabstimmung",
    "s39_title": "Zwischen- & Feinintonation: Die 2-mm-Kronenstiche",
    "s39_subtitle": "Chromatisches Durchhören und vorsichtiges Egalisieren von Einzeltönen",
    "s39_bullet_1": "<strong>Chromatisches Abhören:</strong> Auf- und abwärts durchspielen, um kleinste Ausreißer in Klangfarbe oder Härte zu orten.",
    "s39_bullet_2": "<strong>Zwischenintonation:</strong> Dosiertes Nadeln im Forte- und Piano-Keil; zu weiche Köpfe durch feines Abziehen straffen.",
    "s39_bullet_3": "<strong>Feinintonations-Halter:</strong> Kurze Einzelnadel im BDK-Halter (43-0003269) oder Chop-Stick-Halter (43-0003271).",
    "s39_bullet_4": "<strong>2-mm-Kronenregel:</strong> Am Scheitel höchstens 2 mm tief und ausschließlich zwischen den Saitenrillen einstechen!",
    "s39_caption_1": "Chromatisches Abhören und Feinabstimmung mit kurzer Einzelnadel",
