    "s28_bullet_2": "<strong>Plug &amp; Play Fit:</strong> Direct mounting of pre-calibrated flanges and shanks onto the original rail.",
    "s28_bullet_3": "<strong>On-Site Regulation:</strong> Precise alignment, blow distance, let-off, and checking set right at the grand.",
    "s28_bullet_4": "<strong>Zero Transport Risk:</strong> The grand stays in place and is voiced directly to the room's acoustics.",
