    "s33_kpi3_lbl": "Node Suppression",
    "s33_exp_badge": "✦ ACOUSTIC EFFECT ON PIANO TONE",
    "s33_notes": "Slide 33 (Chapter 5 Opening: Voicing): Interactively demonstrate on bass note A₁ (55 Hz, speaking length L = 1,560 mm) how a piano tone is built from partials H₁–H₁₂. First show felt hardness: a softer, needled hammer lengthens contact time τc (~3.8 ms) and reduces upper partials in dB, whereas a harder crown (τc ~1.3 ms) boosts upper partials sharply. Next demonstrate the Young-Helmholtz strike-point law: striking near 1/8 L or 1/7 L suppresses dissonant partials (H₇ natural seventh, H₉ major second) at their nodes while preserving the singing major third H₅ (1/5 L).",
    "s34_category": "Part 5: Voicing • Vorintonation",
    "s34_title": "Pre-Voicing (Pre-Needling): Deep 90° Stitches in Blue Wedge",
    "s34_subtitle": "Relieving factory pre-tension and channeling elastic energy into the forte wedge",
    "s34_bullet_1": "<strong>Working Zone:</strong> Work strictly inside the blue fortissimo wedge (9:00–10:00 and 2:00–3:00 o'clock).",
    "s34_bullet_2": "<strong>Deep Stitches:</strong> Press smoothly to just above the underfelt—never pierce into underfelt or wood core!",
    "s34_bullet_3": "<strong>Tension Transfer:</strong> Rigid factory stiffness softens as elastic energy flows into the green forte wedge.",
    "s34_bullet_4": "<strong>Best Practice:</strong> Recommended almost without exception before first playing-in inside the piano.",
    "s34_caption_1": "Pre-needling: Deep stitches in the fortissimo wedge (9:00 to 10:00 o'clock)",
    "s34_b1_badge": "PRE-NEEDLING",
    "s34_b2_badge": "BASIC ELASTICITY",
    "s34_c1_desc": "Pre-needling is the essential foundational step on factory-new or newly refelted hammerheads.",
    "s34_kpi": "pp – ff",
    "s34_c1_title": "Targeted Tension Release in the Blue Fortissimo Wedge",
    "s34_fact": "🎯 Unlocks elastic tonal volume without weakening the strike crown",
    "s34_notes": "Slide 39: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s35_category": "Part 5: Voicing • Werkzeug & Technik",
    "s35_title": "Needle Insertion Standards & Voicing Tools",
    "s35_subtitle": "Press, do not chop – Exact stitch counts for bass, mid-range, and treble",
    "s35_bullet_1": "<strong>Bass &amp; Midrange:</strong> Horizontal stitches in the ff wedge—7–10 stitches in the bass and 5–10 in the midrange.",
    "s35_bullet_2": "<strong>Treble Dosage:</strong> Vertically guided stitches of 0–7 insertions depending on desired brilliance and projection.",
    "s35_bullet_3": "<strong>Press, Never Chop:</strong> Push needles smoothly using body weight—chopping tears wool fibers irreversibly!",
    "s35_caption_1": "Renner voicing tools, needle handles, and adjustable voicing instrument",
    "s35_b1_badge": "TOOL SET",
    "s35_b2_badge": "PRECISION NEEDLES",
    "s35_kpi": "No. 7 · ø 0.60 mm",
    "s35_c1_title": "Register Stitch Guidelines & Gentle Needle Technique",
    "s35_c1_desc": "Steady pressing with genuine Renner tools parts the wool fibers cleanly instead of tearing them.",
    "s35_bullet_4": "<strong>Genuine Renner Tools:</strong> Adjustable voicer (43-0005642), 3-needle pro holder (43-0003270), and No. 7 needles (43-0003426).",
    "s35_fact": "🛠 Nickel-plated needles (ø 0.60 mm, 9 mm) glide smoothly between wool fibers",
    "s35_notes": "Slide 40: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s36_category": "Part 5: Voicing • Saitenlagerung",
    "s36_title": "String Preparation: Hitch Pins, Bridge Pins & Leveling",
    "s36_subtitle": "“The finest hammerhead can only reveal what is programmed into the instrument!”",
    "s36_caption_1": "Bedding strings firmly at the hitch pin using brass drift punch",
    "s36_b1_badge": "STRING BEDDING",
    "s36_b2_badge": "UNISON PURITY",
    "s36_bullet_1": "<strong>Seat at Hitch Pins:</strong> Gently tap strings down from back to front at the hitch pins using a brass punch.",
    "s36_bullet_2": "<strong>Seat at Bridge Pins:</strong> Press strings cleanly onto the bridge with the Renner setter to eliminate false beats.",
    "s36_bullet_3": "<strong>Pure Unison Tuning:</strong> Every 3-string unison must ring completely pure and noise-free before voicing begins.",
    "s36_kpi": "100% Unison",
    "s36_c1_title": "Exact String Seating Prior to the First Needle Stitch",
    "s36_c1_desc": "Only cleanly seated and purely tuned string unisons permit an honest acoustic diagnosis of the hammerhead.",
    "s36_fact": "🎵 Golden Rule: No needle can fix a poorly seated or impure string unison!",
    "s36_notes": "Slide 41: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s37_category": "Part 5: Voicing • Ausrichtung",
    "s37_title": "Treble Strike Point Alignment & Hammer Straightness",
