    "s2_c4_desc": "ヤマハ専用ドロップイン・キット：1本のネジで直装、約10時間の工数を削減、穴あけ・接着不要で即座にコンサート音色を実現。",
    "s2_c5_desc": "A₁ (55 Hz) の倍音構造と打弦点、予備針入れ、弦レベル合わせ、クラウン整形、ウナ・コルダ微調整。",
    "s2_notes": "スライド 2: マスタークラスの5大主要モジュール（歴史とモイゼルヴィッツ新拠点、ヴルツェンでのフェルト製造、ハンマーヘッド製造、注目ハイライトのヤマハKIT、至高の整音技術）を紹介します。",
    "s3_category": "第1部：序論とモイゼルヴィッツ新拠点",
    "s3_title": "140余年の伝統と究極の精密工学（1882年〜現代）",
    "s3_subtitle": "シュトゥットガルトの手工業工房からKlaviermechanik・Hammerheadの世界最高峰リーダーへ",
    "s3_notes": "スライド 3: 140余年の歴史年表（全9節目）。注目は節目1（1882年：シュトゥットガルト創業 — ホイシュタイグ通りの工房でアクションから始まった歴史；カール・レーニッシュ総鉄骨フレーム革新との呼応）、節目2（1906年：自社ハンマーヘッド製造開始 — 1700年のクリストフォリによる革巻き紙ロールから1906年のレンナー自社生産へ。後にすべてのスタインウェイの響きを決定づけ世界基準を確立；クリストフォリ、1700年アクション、歴史的機械製造、1906年プレス機画像シリーズ）、節目3（1911年：電化革命とグランドピアノ機構 — エラールのレペティション機構を礎とする近代グランド演奏；レンナー初のグランド用アクション自社製造への飛躍；オスカー・レンナーによる最新工作機械・省力化工法・総軸から数百基の独立電動モーターへの転換；全工程の内製化；エラール、1808年機構、電化工房画像シリーズ）、節目4（1944年空襲と再建）、節目5（1951/1952年：マンフレート・レンナー博士）、節目6（1990年：ベルリンの壁崩壊と存亡を賭けたツァイツ工場買収 — チェコ製メーカー台頭の中で1日40台以上を生産する最大顧客シンメル社を守り抜いた歴史的転換点）、節目7（2011年：ゲルトリンゲン新社屋とツァイツからモイゼルヴィッツへの移転・最新生産拠点展開；2大拠点体制の確立；ゲルトリンゲン新社屋と上空からのモイゼルヴィッツ拠点画像シリーズ）、節目8（2019年：スタインウェイ買収と故アルニム氏追悼）、そして節目9（伝統を守り未来を創る：2025年10月始動の全プロセス・モイゼルヴィッツ統合完了と最新の集中集塵・排気フィルター設備導入、ゲルトリンゲン社員への深謝）。",
