    "s5_hl2_title": "合成樹脂不使用の純粋縮絨：",
    "s5_hl2_desc": "ムルデ川の水・熱・圧力のみで圧縮。音色を濁らせる接着剤や化学樹脂は一切不使用。",
    "s5_hl3_title": "永続的な超高速リバウンド：",
