    "s5_c1_title": "ヴァイケルト・フェルトの秘密",
    "s5_c1_desc": "化学添加物を一切排した純機械的縮絨 — コンサートグランドの響きの魂",
    "s5_notes": "スライド 5: ヴルツェンフェルト工場（FFW）のヴルツェンにおける1783年創業からの歴史と、ヴァイケルト・フェルトの音響的秘密。全6つの歴史的節目を紹介：1783年ヴルツェン創業、1847年ドイツ初のピアノフェルト開発（革巻きからの転換）、1850〜67年万博金メダル、1861年ミュールグラーベン大工場での蒸気機械化と軟水活用、1906年年間20万台分の世界首位供給、そして現代のルイス・レンナー専用「ヴァイケルト・シュペツィアル」復刻。特にヴルツェン工場とレンナー・モイゼルヴィッツ本工場との極近距離（わずか約65km）を強調してください。職人同士の直接対話、最短の輸送経路、完璧な品質調整を可能にしています。",
    "s6_category": "第2部：極上フェルト製造の秘密（ヴルツェン工場）",
    "s6_title": "厳選バージンウール：天然繊維の弾力性保護",
