    "s22_subtitle": "Nachspannen des Kernholzes zur Erzeugung maximaler elastischer Außenspannung",
    "s22_bullet_1": "<strong>サイド型の閉鎖：</strong> 温調されたプレス型がフェルトを側面から包み込み、接着コアへ密着させます。",
    "s22_bullet_2": "<strong>高圧の追い締め：</strong> 型が閉じた状態でウッドコアをさらに高圧でクラウン方向へ押し込みます。",
    "s22_bullet_3": "<strong>外層の引張・内層の圧縮：</strong> 外層に強い張力を与えつつ、内層にしなやかな弾性クッションを形成します。",
    "s22_bullet_4": "<strong>整音ポテンシャルの源泉：</strong> 蓄えられた内部張力がppからffまで圧倒的なダイナミックレンジを叶えます。",
    "s22_caption_1": "Press- und Verleimvorgang des Hammerkopfs unter Hochdruck",
