    "s27_category": "第4部：YAMAHA 専用キット・製品紹介",
    "s27_title": "Louis Renner Yamaha Kit (C1–C3) — シームレス導入",
    "s27_subtitle": "ヤマハ C1〜C3 専用設計：豊かなダイナミクス、輝かしい倍音、重厚な低音の深み。",
    "s27_play_label": "プレゼンテーション再生",
    "s27_tab1_tag": "高精度計測システム",
    "s27_tab2_tag": "最適重量・タッチ",
    "s27_tab3_tag": "ネジ留め・整列",
    "s27_tab4_tag": "コンサートトーン",
    "s27_tab5_tag": "数日を数時間に短縮",
    "s27_b1_badge": "測定基準製造・5年間の研究開発",
    "s27_p1_title": "独自計測・製造システム",
    "s27_p1_subtitle": "新品・既存のヤマハC1〜C3に、比類なき至高の響きを。",
    "s27_p1_bullet_1": "<strong>完全同期システム：</strong>5年の開発を経て、フェルトの密度・弾性・張力を高精度に制御。",
    "s27_p1_bullet_2": "<strong>確かなターゲットトーン：</strong>C1〜C3の音響最適値に合わせて全セットを高精度に再現製造。",
    "s27_p1_bullet_3": "<strong>針入れ不要の音色：</strong>手作業の予備整音なしで、直ちに深みある温かな響きを実現。",
    "s27_p1_fact": "✦ 確かなコンサート品質：出荷時からマスタークラスの響き",
    "s27_b2_badge": "レンナー計測システム",
    "s27_p1_caption": "事前校正済みハンマーセット：手作業の針入れなしで完璧な響き",
    "s27_b3_badge": "慣性モーメント最適化",
    "s27_p2_title": "最適重量バランスと俊敏な連打性",
    "s27_p2_subtitle": "校正済みウォルナット木芯と精密シャンクにより、軽快なタッチレスポンスを実現。",
    "s27_p2_bullet_1": "<strong>校正済みウォルナット芯：</strong>軽量な響芯が慣性モーメントを低減し、軽快な演奏性を実現。",
    "s27_p2_bullet_2": "<strong>厳選シデ材：</strong>緻密な柾目材が最高の曲げ剛性とピュアな振動伝達を保証。",
    "s27_p2_bullet_3": "<strong>高張力ローラー：</strong>高張力下で接着され、優れた復元力で俊敏な連打を実現。",
    "s27_p2_fact": "✦ 圧倒的な時間短縮：現場にてわずか4〜5時間で全交換と精密調整が完了",
    "s27_b4_badge": "重量とジオメトリ",
    "s27_p2_caption": "ヤマハC1〜C3に校正されたシャンク＆フランジ：繊細なタッチ感",
    "s27_b5_badge": "ネジ留め・整列・完了",
    "s27_p3_title": "ネジ留め・整列・完了。",
    "s27_p3_subtitle": "フランジ接着済み完成セット — 工場にて伝統の天然膠で強固に固定。",
    "s27_p3_bullet_1": "<strong>ネジ1本で簡単固定：</strong>ヤマハ純正アルミレールへ1音ずつ直接ネジ留め可能。",
    "s27_p3_bullet_2": "<strong>高精度ボーリング：</strong>最適角度で穿孔済み — 工房での測定や穴あけ作業が不要。",
    "s27_p3_bullet_3": "<strong>高硬度ニカワ接着：</strong>ガラス状に結晶化し、減衰のないダイレクトな振動伝達を実現。",
    "s27_p3_fact": "✦ 最高の作業安全性：穴あけや接着のミスリスクを完全排除",
    "s27_b6_badge": "プラグ＆プレイ",
    "s27_p3_caption": "91°の角度で膠付けされた完成品：ヤマハ純正レールへ直付け可能",
    "s27_b7_badge": "倍音豊かなコンサートトーン",
    "s27_p4_title": "豊かな倍音スペクトルと多彩な音色",
    "s27_p4_subtitle": "温かみある欧州のピアニッシモから、フォルティッシモの力強い響きまで。",
    "s27_p4_bullet_1": "<strong>均一な一枚フェルト：</strong>一体成型により、88鍵すべての音域移行を完璧にスムーズ化。",
    "s27_p4_bullet_2": "<strong>明瞭な基音低音部：</strong>最適質量と高弾性フェルトが、深みある響きと澄んだ音の分離を創出。",
    "s27_p4_bullet_3": "<strong>澄み渡る鐘の高音：</strong>軽量芯と頂点部高密度圧縮が、長く歌い通る高音部を創出。",
    "s27_p4_fact": "✦ 音響の昇華：鋭い打撃音を、温かく伸びやかなコンサートトーンへ変貌",
    "s27_b8_badge": "音色とダイナミクス",
    "s27_p4_caption": "1枚の均一なフェルト帯から製造：音域間の段差が一切ないシームレスな音色推移",
    "s27_b9_badge": "数日を数時間に短縮",
    "s27_p5_title": "工房での3〜7日から、現場での4〜5時間へ",
    "s27_p5_subtitle": "数日間の工房作業 vs. ピアノの前で即日完了する交換と精密調整。",
    "s27_p5_bullet_1": "<strong>従来の作業（3〜7日）：</strong>搬出、旧ヘッド脱膠、穿孔測定、温膠、整列、ファイリング、予備整音。",
    "s27_p5_bullet_2": "<strong>レンナーキット（4〜5時間）：</strong>直付けし、弦合わせとクラウンを整列 — 必要に応じて最終整音。",
    "s27_p5_bullet_3": "<strong>現場対応・室内音響：</strong>搬出リスクゼロ — 部屋の音響特性や顧客の好みに合わせた音色作りに集中可能。",
    "s27_p5_fact": "✦ 絶大なる経済性：数日間の重労働をわずか数時間の現場作業に圧縮",
    "s27_b10_badge": "効率比較",
    "s27_p5_caption": "25年経過した摩耗ハンマー（右） vs. 新品のレンナー製コンサートハンマー（左）",
    "s27_b11_badge": "レンナー YAMAHA キット",
