    "s27_hl1_title": "校正済みシステム：",
    "s27_hl1_desc": "独自計測工法により、予備整音なしで出荷時から完成された響きを提供。",
    "s27_hl2_title": "ウォルナット＆シデ材：",
    "s27_hl2_desc": "慣性モーメントを極小化し、俊敏な連打性と軽快なタッチレスポンスを実現。",
    "s27_hl3_title": "ドロップイン＆膠接着：",
    "s27_hl3_desc": "91°の角度でニカワ接着済み — 減衰のない高剛性結合と穴あけ作業ゼロ。",
    "s27_hl4_title": "ネジ1本簡単装着：",
    "s27_hl4_desc": "純正レールへ直付け — 現場にてわずか4〜5時間で換装と調整が完了。",
    "s27_notes": "スライド 27: 核心となる技術革新を強調してください：5年間の研究開発から生まれた独自の測定・製造システムにより、理想的な音響スペクトルに合わせて精密に事前校正されています。その響きは新品のヤマハC1〜C3純正ハンマーをも凌駕し、針入れによる予備整音は一切不要です。日常的に整音を行わない技術者にとっても失敗のリスクがありません。ネジ1本での取り付けと高張力ローラーにより、工房での3〜7日の重労働が現場でのわずか4〜5時間に短縮されます。搬出リスクがなく、部屋の響きに合わせた音色調整に十分な時間を割くことができます。",
