    "s28_bullet_2": "<strong>プラグ＆プレイ装着：</strong> 較正済みフレンジとシャンクを純正アルミレールへそのままネジ固定。",
    "s28_bullet_3": "<strong>現地での精密整調：</strong> 弦合わせ・打弦距離・レットオフ・バックチェックをその場で最適化。",
    "s28_bullet_4": "<strong>搬出リスクゼロ：</strong> 楽器を移動させず、設置空間の音響特性に合わせて直接仕上げます。",
