    "s29_title": "ピアニスト評価：ピアニスト Raaga による実演レビュー",
    "s29_subtitle": "改装されたヤマハ・グランドピアノにおける音色、ダイナミクス、連打性への直接評価",
    "s29_b1_badge": "ピアニスト実演評価",
    "s29_m1_unit": "出荷時からのコンサートトーン",
    "s29_bullet_1": "<strong>歌うコンサートトーン：</strong> 硬質なアタックから温かく豊かな響きへの劇的な変化を即実感。",
    "s29_bullet_2": "<strong>華やかな高音と明瞭な低音：</strong> 澄んだ旋律の伸びと低音域でのクリアな和音分離を両立。",
    "s29_bullet_3": "<strong>繊細なダイナミクス制御：</strong> 囁くようなppから力強いffまで自在な音色表現が可能に。",
    "s29_bullet_4": "<strong>軽快な連打性能：</strong> 最適化されたハンマー質量が素早い復原力と鋭敏な反応を実現。",
    "s29_kpi": "コンサート音色",
    "s29_c1_title": "交換直後のピアニストによる実演評価",
