    "s31_notes": "スライド29では、選択した2オクターブ領域における基音（H1）から第12倍音（H12）までの倍音分布を解析します。左側は12倍音の比較グラフ、右側は24半音すべてのノート別倍音エネルギー（H2〜H8）です。",
    "s32_category": "第4部：ヤマハ・キット • 音響解析 (3/3)",
    "s32_title": "4大音響メリット＆スペクトルスロープ計算機 (最大 C8)",
