    "s32_calc_r2": "Rennerキット (−6.45 dB/kHz)",
    "s32_calc_r3": "純ゲイン",
    "s32_notes": "スライド32の左側では、Louis Renner ヤマハ・キットの4大音響メリット（歌唱域+2.53 dB / +79%、高音域+1.87 dB / +54%、低音の透明化−3.28 dB、スロープ+0.93 dB/kHz改善＆クレスト+0.42 dB）を一覧化。右側では打鍵ダイナミクス別のスペクトルスロープ回帰図と最高音C8（最大4,300 Hz）対応のライブ計算機を表示します。",
    "s33_category": "第5部：整音技術 • 導入：ピアノ音の倍音構造と音響物理",
    "s33_title": "A₁ (55 Hz) の倍音構造：フェルト硬度と打弦点の影響",
