    "s5_category": "第二部分：琴毡制造 • 历史与传统",
    "s5_title": "乌尔岑毛毡厂（FFW）– 顶级钢琴弦槌毛毡的诞生地",
    "s5_subtitle": "乌尔岑 1783 • 从1847年德国首创工业琴毡到雷诺专属“魏克特特级”深度合作",
    "s5_play_label": "播放时光之旅",
    "s5_tab1_tag": "乌尔岑 1783",
    "s5_tab2_tag": "首创琴毡",
    "s5_tab3_tag": "世博金奖",
