    "s5_c1_title": "魏克特毛毡的不传之秘",
    "s5_c1_desc": "不含任何化学添加剂的纯物理机械缩绒 — 赋予音乐会三角琴纯净深邃的声学灵魂",
    "s5_notes": "第 5 页：乌尔岑毛毡厂（FFW）自1783年创立于乌尔岑以来的传奇厂史与魏克特高级琴毡的声音奥秘。生动呈现六大历史里程碑：1783年在乌尔岑创立、1847年德国首创工业钢琴纯羊毛毡、1850-1867年世博金奖与国王盛赞、1861年水渠沿岸蒸汽机械化大工场与穆尔德纯净软水、1906年年供20万架钢琴的世界霸主地位，以及专为雷诺重生的“魏克特特级”。特别重点强调乌尔岑毛毡厂与雷诺迈泽尔维茨总厂极近的地理空间优势（相距仅约65公里）：实现制毡大师与弦槌大师零距离深度实时交流调校、零延时物流与极其严密的音色匹配。",
    "s6_category": "第二部分：顶级纯羊毛毡制造工艺（乌尔岑毛毡厂）",
    "s6_title": "纯正天然美利奴羊毛：极度呵护天然纤维弹性",
    "s6_subtitle": "Nur unverpresste Rohwolle garantiert die maximale natürliche Elastizität",
    "s6_bullet_1": "<strong>非过压原毛包运输：</strong> 松散打包运输原毛，完整保留羊毛纤维细腻的鳞片层与天然卷曲弹性。",
    "s6_bullet_2": "<strong>Höhere Logistikkosten für Spitzenqualität:</strong> Dieser schonende Transport erhöht das Transportvolumen, sichert jedoch die unversehrte Faserelastizität.",
    "s6_bullet_3": "<strong>Starke Faserkräuselung:</strong> Nur hochgradig gekräuselte Merinowollfasern bieten beim späteren Walkprozess den optimalen Verhakungseffekt.",
    "s6_bullet_4": "<strong>Schonende Carbonisierung:</strong> Chemisch sanftes Reinigungsverfahren entfernt Pflanzenteilchen, ohne die Proteinstruktur des Keratins anzugreifen.",
    "s6_caption_1": "原毛入厂：FFW采用非压缩毛包储存以保护天然纤维卷曲",
