    "s22_bullet_1": "<strong>温控侧模闭合：</strong> 恒温加热模具从两侧包拢毛毡条，使其紧密贴合涂胶木芯。",
    "s22_bullet_2": "<strong>高压二次顶紧：</strong> 在侧模锁死状态下，以强大推力将实木槌芯向槌冠方向再次顶紧。",
    "s22_bullet_3": "<strong>外紧内韧结构：</strong> 外层纤维获得极高拉伸预应力，内层则保持充沛的压缩回弹支撑。",
    "s22_bullet_4": "<strong>整音潜能基石：</strong> 充沛的弹性预应力储备赋予从极弱音（pp）到极强音（ff）的宽广动态。",
    "s22_caption_1": "Press- und Verleimvorgang des Hammerkopfs unter Hochdruck",
