    "s28_bullet_2": "<strong>即插即用安装：</strong> 将预校准轴架与槌柄直接旋入雅马哈原厂铝合金总档。",
    "s28_bullet_3": "<strong>现场精密整调：</strong> 直接在琴上完成对弦、击弦距离、脱进与档托的精准调校。",
    "s28_bullet_4": "<strong>零搬运风险：</strong> 三角琴无需运回工坊，直接结合现场空间声学完成最终匹配。",
