    "s28_c1_title": "在钢琴安放现场一天内完成全套换装",
    "s28_c1_desc": "印度现场纪实：10:00至18:00当日完成雷纳雅马哈套件换装与全套精密整调。",
    "s28_fact": "⏱ 10:00–18:00：从拆卸旧槌到音乐会级交付，当日现场一步到位",
    "s28_notes": "幻灯片 28：展示印度现场全天安装延时摄影（10:00至18:00）。仅用1个现场工作日即完成雅马哈三角钢琴全套雷纳套件的更换与精调。",
    "s29_category": "第4部分：雅马哈套件 • 印度现场安装实证 (2/2)",
    "s29_title": "钢琴家反馈：钢琴家 Raaga 现场实测评价",
    "s29_subtitle": "改装后雅马哈三角钢琴在音色、动态范围与复振性能上的艺术家直接评价",
    "s29_b1_badge": "钢琴家现场实证",
    "s29_m1_unit": "出厂即享音乐会音色",
    "s29_bullet_1": "<strong>如歌音乐会音色：</strong> 从生硬敲击感立即蜕变为温暖醇厚、富有穿透力的共鸣。",
    "s29_bullet_2": "<strong>通透高音与清晰低音：</strong> 旋律音区如钟鸣般延展，低音和弦层次清晰分明。",
    "s29_bullet_3": "<strong>细腻动态层次：</strong> 从极弱音（pp）到极强音（ff）皆可自如塑造丰富音色变化。",
    "s29_bullet_4": "<strong>轻盈敏捷复奏：</strong> 得益于精准标定的弦槌质量，触键回弹与连奏更加灵敏。",
    "s29_kpi": "音乐会级音色",
    "s29_c1_title": "换装完成后钢琴家的现场即刻品鉴",
    "s29_c1_desc": "钢琴家 Raaga 现场试奏升级后的雅马哈三角琴，检验其温暖度、穿透力与触键感。",
    "s29_fact": "🎹 立竿见影蜕变为温暖醇厚的欧洲音色与细腻触键控制",
    "s29_notes": "幻灯片 29：播放钢琴家Raaga的反馈视频。她在安装雷纳雅马哈套件后立即肯定了更加温暖歌唱的音乐会音色及敏锐的触键控制。",
