    "s32_adv4_title": "斜率平缓 12.6% 且波峰提升 +0.42 dB",
    "s32_adv4_desc": "泛音更丰富（−6.45 dB/kHz），触键瞬态响应更敏捷。",
    "s32_r_badge": "频谱斜率 (上限 C8 = 4,300 HZ)",
    "s32_r_title": "动态斜率与实时计算器",
    "s32_calc_title": "🧮 实时计算器 (至 C8 = 4,300 Hz):",
    "s32_calc_lbl": "频率 f:",
    "s32_calc_r1": "原装 (−7.38 dB/kHz)",
