    "s32_calc_r3": "净增益",
    "s32_notes": "第 32 页左侧汇总了 Louis Renner 雅马哈套件的四大实测声学优势（歌唱区 +2.53 dB / +79%、高音辉煌感 +1.87 dB / +54%、低音清晰度去浑 −3.28 dB，以及斜率平缓 +0.93 dB/kHz 与波峰提升 +0.42 dB）。右侧展示全动态范围（pp–ff）频谱斜率散点回归图与上限至钢琴最高音 C8（4,186 Hz / 最大 4,300 Hz）的实时计算器。",
    "s33_category": "第五部分：整音艺术 • 开篇：钢琴乐音泛音结构与击弦声学",
    "s33_title": "A₁ (55 Hz) 泛音结构解析：弦槌硬度与击弦点位置",
    "s33_subtitle": "弦槌毛毡弹性与击弦点比例对第 1–12 泛音（H₁–H₁₂）分贝（dB）增减的声学调控",
