    "s33_kpi1_lbl": "低音基频 (H₁–H₄)",
    "s33_kpi1_sub": "55–220 Hz 基音与丰满度",
    "s33_kpi2_lbl": "高次泛音 (H₆–H₁₂)",
    "s33_kpi2_sub": "330–660 Hz 明亮度与穿透力",
    "s33_kpi3_lbl": "波节抑制",
    "s33_exp_badge": "✦ 钢琴乐音声学作用机制",
    "s33_notes": "第 33 页（第五部分整音开篇）：以低音 A₁（55 Hz，有效弦长 L = 1,560 mm）为例，交互演示钢琴音色由 H₁–H₁₂ 泛音构成的物理本质。首先演示弦槌软硬度：刺针柔化延长接触时间 τc（约 3.8 ms），以分贝（dB）为单位衰减高次泛音；高密硬槌（τc 约 1.3 ms）则大幅拉升高频泛音。随后演示杨-亥姆霍兹击弦点定律：在 1/8 L 或 1/7 L 处击弦可在波节处精准抑制不协和的 H₇（自然七度）与 H₉（大二度），同时保留决定歌唱色彩的大三度 H₅（1/5 L）。",
    "s34_category": "第七部分：钢琴整音大师秘籍",
    "s34_title": "初期预整音（Pre-Needling）：蓝色极强音楔区深度垂直扎针释放死应力",
    "s34_subtitle": "Abbau werkseitiger Vorspannung und Energieübertragung in den Forte-Keil",
    "s34_bullet_1": "<strong>施针区域：</strong> 严格限定在蓝色极强音扇区（9:00–10:00 及 2:00–3:00 钟点方向）作业。",
    "s34_bullet_2": "<strong>深层进针：</strong> 平稳推针至底毡上方即止——严禁刺穿底毡或伤及实木槌芯！",
    "s34_bullet_3": "<strong>张力传递：</strong> 化解出厂时的僵硬紧绷感，使充沛的弹性势能顺畅导入绿色强音扇区。",
    "s34_bullet_4": "<strong>实战标准流程：</strong> 在装入钢琴首次试奏前，几乎毫无例外建议先行完成此步基础整音。",
    "s34_caption_1": "预整音：在极强音扇区（9:00至10:00方向）进行深层刺针",
    "s34_b1_badge": "基础刺针整音",
    "s34_b2_badge": "建立核心弹性",
    "s34_c1_desc": "预整音（Pre-Needling）是全新弦槌或新包毛毡弦槌装琴前至关重要的基础工序。",
    "s34_kpi": "pp – ff 全动态",
    "s34_c1_title": "蓝色极强音扇区的定向预应力释放",
    "s34_fact": "🎯 在丝毫不削弱槌冠强度的前提下，充分释放毛毡的弹性共鸣潜能",
    "s34_notes": "第 59 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
    "s35_category": "第七部分：钢琴整音大师秘籍",
    "s35_title": "进针深度、角度与专业排针/单针整音工具规范",
    "s35_subtitle": "Drücken statt Hacken – Exakte Stichanzahlen für Bass, Mittellage und Diskant",
    "s35_bullet_1": "<strong>低音与中音区规范：</strong> 于ff扇区水平进针——低音区7–10针，中音区5–10针。",
    "s35_bullet_2": "<strong>高音区精细定量：</strong> 视所需明亮度与穿透力，沿垂直方向精准施针0–7次。",
    "s35_bullet_3": "<strong>稳压而非劈刺：</strong> 借助身体重心平稳推针入毡——猛烈劈刺会不可逆地撕裂羊毛纤维！",
    "s35_caption_1": "Renner Intonierwerkzeuge, Nadelhalter und Intonierapparat",
    "s35_b1_badge": "专业整音工具",
    "s35_b2_badge": "进口精密排针",
    "s35_kpi": "7号针 · ø 0.60 mm",
    "s35_c1_title": "各音区标准刺针数与不伤纤维的稳压针法",
    "s35_c1_desc": "使用原厂工具平稳压入，能够柔和拨开羊毛纤维而不将其暴力扯断。",
    "s35_bullet_4": "<strong>雷纳原厂工具组：</strong> 可调整音器（43-0005642）、三针专业针柄（43-0003270）及7号镀镍针（43-0003426）。",
    "s35_fact": "🛠 镀镍精密整音针（ø 0.60 mm，长 9 mm）顺滑穿行于纤维间隙而不伤毛网",
    "s35_notes": "第 60 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
    "s36_category": "第七部分：钢琴整音大师秘籍",
    "s36_title": "弦列声学校准：弦枕销敲实、挂弦销紧固与同音弦三弦同高平整",
    "s36_subtitle": "„Der beste Hammerkopf kann nur das hervorbringen, was im Instrument programmiert ist!“",
    "s36_caption_1": "Saiten niederschlagen am Anhangstift mit Messingdurchschlag",
    "s36_b1_badge": "琴弦沉实就位",
    "s36_b2_badge": "三弦同音纯净",
    "s36_bullet_1": "<strong>挂弦钉落座贴合：</strong> 用黄铜冲子配合轻锤由后向前轻敲，使琴弦在挂弦钉处稳固服帖。",
    "s36_bullet_2": "<strong>码钉压实贴合：</strong> 使用雷纳专用压弦器将琴弦稳压于音板弦码，彻底消除假拍与杂音。",
    "s36_bullet_3": "<strong>纯净同度调律：</strong> 在下针整音前，每一组三弦同度必须调至零拍音、零杂音的纯净状态。",
    "s36_kpi": "100% 同度纯净",
    "s36_c1_title": "动针整音前必须确保琴弦贴合与同度纯净",
    "s36_c1_desc": "唯有琴弦稳固贴合且同度弦组绝对纯净，方能真实判断弦槌本身的声学状态。",
    "s36_fact": "🎵 黄金准则：任何刺针整音都无法弥补琴弦虚浮或同度不纯的缺陷！",
    "s36_notes": "第 61 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
    "s37_category": "第七部分：钢琴整音大师秘籍",
    "s37_title": "高音区击弦点最佳纵深定位与弦槌三弦垂直平行对准",
    "s37_subtitle": "Optimierung der Noten 69–88 durch Verschieben des Klaviaturrahmens",
    "s37_bullet_1": "<strong>第88键基准寻优：</strong> 前后微移键盘架，直至找到高音最明亮饱满、共鸣最通透的最佳击弦位置。",
    "s37_bullet_2": "<strong>69–88键显著蜕变：</strong> 精准校准高音区击弦点，往往能让三角钢琴的高音歌唱性获得质的飞跃。",
    "s37_bullet_3": "<strong>运行轨迹与对正检验：</strong> 轻抬顶杆或用拨钩检查槌头起落垂直度，并用粉笔在琴键上标记偏差音。",
    "s37_caption_1": "Prüfung des Diskant-Anschlagspunkts und Ausrichtung der Hämmer",
    "s37_b1_badge": "最佳击弦点",
    "s37_b2_badge": "高音晶莹通透",
    "s37_kpi": "第 69–88 键",
    "s37_c1_title": "高音区最佳击弦点寻优与弦槌精准对正",
    "s37_c1_desc": "在高音区，键盘架前后哪怕零点几毫米的微调，都直接决定音色的穿透力与泛音光泽。",
    "s37_fact": "✨ 精整音前先校准击弦几何位置，可避免大量不必要的盲目刺针",
    "s37_notes": "第 62 页：向嘉宾介绍核心要点，重点阐述德国雷诺不可替代的高精机械与音色标准。",
    "s38_category": "第七部分：钢琴整音大师秘籍",
    "s38_title": "槌顶打磨整形（Filing）：凹陷、偏斜与饱满平滑弧度的正确砂光",
    "s38_subtitle": "Anpassung der Scheitelfläche an den 3-chörigen Saitenverlauf mit feiner Hammerfeile",
    "s38_c1_title": "1. 槌冠中凹（Hollow Crown）",
    "s38_c2_title": "2. 槌冠偏斜（Crooked Crown）",
